import sys
from collections import defaultdict

def main(input_path, output_path, submission_path):
    with open(input_path) as f:
        n = int(f.readline().strip())

    with open(submission_path) as f:
        lines = f.read().splitlines()

    if not lines:
        print(0)
        return

    first_line = lines[0].strip()
    if first_line == '-1':
        print(0)
        return

    try:
        k = int(first_line)
    except:
        print(0)
        return

    if not (1 <= k <= n * n):
        print(0)
        return

    if len(lines) != k + 1:
        print(0)
        return

    edges = defaultdict(int)

    for line in lines[1:k+1]:
        parts = line.strip().split()
        if not parts:
            print(0)
            return
        try:
            m = int(parts[0])
        except:
            print(0)
            return
        if m not in (3,4):
            print(0)
            return
        if len(parts) != m +1:
            print(0)
            return
        vs = list(map(int, parts[1:]))
        if any(v <1 or v >n for v in vs):
            print(0)
            return
        if len(set(vs)) != m:
            print(0)
            return
        for i in range(m):
            u = vs[i]
            v = vs[(i+1) % m]
            edge = tuple(sorted((u, v)))
            edges[edge] +=1

    for u in range(1, n+1):
        for v in range(u+1, n+1):
            if edges.get((u, v), 0) != 2:
                print(0)
                return

    print(1)

if __name__ == "__main__":
    import sys
    input_path = sys.argv[1]
    output_path = sys.argv[2]
    submission_path = sys.argv[3]
    main(input_path, output_path, submission_path)
